import java.io.*;
import java.util.*;

public class Main {
    static int n, q;
    static long k;
    static long[] heights;
    static long[] bValues, cValues;
    static int[] bId, cId;
    static int[] bMinus, bPlus, cMinus, cPlus;
    static Occurrences bOccurrences, cOccurrences;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int ch;
            do {
                ch = read();
            } while (ch <= ' ' && ch != -1);

            long value = 0;
            while (ch > ' ') {
                value = value * 10 + (ch - '0');
                ch = read();
            }
            return value;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Occurrences {
        final int[] offsets;
        final int[] positions;

        Occurrences(int[] ids, int uniqueCount) {
            int[] counts = new int[uniqueCount];
            for (int id : ids) counts[id]++;

            offsets = new int[uniqueCount + 1];
            for (int i = 0; i < uniqueCount; i++) {
                offsets[i + 1] = offsets[i] + counts[i];
            }

            positions = new int[ids.length];
            int[] cursor = offsets.clone();

            // Percorrer os índices em ordem já deixa cada lista ordenada.
            for (int i = 0; i < ids.length; i++) {
                positions[cursor[ids[i]]++] = i;
            }
        }

        int countInRange(int id, int left, int right) {
            if (id < 0 || left > right) return 0;

            int start = offsets[id];
            int end = offsets[id + 1];

            int lo = lowerBound(positions, start, end, left);
            int hi = upperBound(positions, start, end, right);
            return hi - lo;
        }

        private static int lowerBound(int[] arr, int lo, int hi, int value) {
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (arr[mid] < value) lo = mid + 1;
                else hi = mid;
            }
            return lo;
        }

        private static int upperBound(int[] arr, int lo, int hi, int value) {
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (arr[mid] <= value) lo = mid + 1;
                else hi = mid;
            }
            return lo;
        }
    }

    static class Node {
        int left, right;
        int pivot = -1;
        int leftChild = -1, rightChild = -1;

        Node(int left, int right) {
            this.left = left;
            this.right = right;
        }
    }

    static long countLeaf(int left, int right, int[] freqB, int[] freqC) {
        long result = 0;

        for (int i = left; i <= right; i++) {
            if (bMinus[i] >= 0) result += freqB[bMinus[i]];
            if (cMinus[i] >= 0) result += freqC[cMinus[i]];

            freqB[bId[i]]++;
            freqC[cId[i]]++;
        }

        // Remover as duplicações: distância K e alturas iguais.
        if (k < n) {
            int distance = (int) k;
            for (int i = left + distance; i <= right; i++) {
                if (heights[i] == heights[i - distance]) result--;
            }
        }

        // Limpar as frequências usadas nesta folha.
        for (int i = left; i <= right; i++) {
            freqB[bId[i]]--;
            freqC[cId[i]]--;
        }

        return result;
    }

    static long countRemoved(Node node) {
        int d = node.pivot;
        int leftL = node.left;
        int leftR = d - 1;
        int rightL = d + 1;
        int rightR = node.right;

        long xIncident = 0;
        long cIncident = 0;

        // Pares entre o lado esquerdo e o degrau removido.
        xIncident += bOccurrences.countInRange(bMinus[d], leftL, leftR);
        cIncident += cOccurrences.countInRange(cMinus[d], leftL, leftR);

        // Pares entre o degrau removido e o lado direito.
        xIncident += bOccurrences.countInRange(bPlus[d], rightL, rightR);
        cIncident += cOccurrences.countInRange(cPlus[d], rightL, rightR);

        long overlapIncident = 0;
        if (k < n) {
            int distance = (int) k;
            int before = d - distance;
            int after = d + distance;

            if (before >= node.left && heights[before] == heights[d]) {
                overlapIncident++;
            }
            if (after <= node.right && heights[after] == heights[d]) {
                overlapIncident++;
            }
        }

        long incident = xIncident + cIncident - overlapIncident;

        // Pares que cruzam do lado esquerdo para o lado direito.
        int leftSize = Math.max(0, leftR - leftL + 1);
        int rightSize = Math.max(0, rightR - rightL + 1);

        long xCross = 0;
        long cCross = 0;
        long overlapCross = 0;

        if (leftSize <= rightSize) {
            for (int i = leftL; i <= leftR; i++) {
                xCross += bOccurrences.countInRange(bPlus[i], rightL, rightR);
                cCross += cOccurrences.countInRange(cPlus[i], rightL, rightR);

                long other = i + k;
                if (other >= rightL && other <= rightR
                        && heights[i] == heights[(int) other]) {
                    overlapCross++;
                }
            }
        } else {
            for (int j = rightL; j <= rightR; j++) {
                xCross += bOccurrences.countInRange(bMinus[j], leftL, leftR);
                cCross += cOccurrences.countInRange(cMinus[j], leftL, leftR);

                long other = j - k;
                if (other >= leftL && other <= leftR
                        && heights[(int) other] == heights[j]) {
                    overlapCross++;
                }
            }
        }

        long cross = xCross + cCross - overlapCross;
        return incident + cross;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        n = fs.nextInt();
        q = fs.nextInt();
        k = fs.nextLong();

        heights = new long[n];
        bValues = new long[n];
        cValues = new long[n];

        for (int i = 0; i < n; i++) {
            heights[i] = fs.nextLong();
            bValues[i] = i + heights[i];
            cValues[i] = i - heights[i];
        }

        long[] sortedB = bValues.clone();
        long[] sortedC = cValues.clone();
        Arrays.sort(sortedB);
        Arrays.sort(sortedC);

        int uniqueBCount = uniqueCount(sortedB);
        int uniqueCCount = uniqueCount(sortedC);
        long[] uniqueB = Arrays.copyOf(sortedB, uniqueBCount);
        long[] uniqueC = Arrays.copyOf(sortedC, uniqueCCount);

        bId = new int[n];
        cId = new int[n];
        bMinus = new int[n];
        bPlus = new int[n];
        cMinus = new int[n];
        cPlus = new int[n];

        for (int i = 0; i < n; i++) {
            bId[i] = Arrays.binarySearch(uniqueB, bValues[i]);
            cId[i] = Arrays.binarySearch(uniqueC, cValues[i]);

            bMinus[i] = Arrays.binarySearch(uniqueB, bValues[i] - k);
            bPlus[i] = Arrays.binarySearch(uniqueB, bValues[i] + k);
            cMinus[i] = Arrays.binarySearch(uniqueC, cValues[i] - k);
            cPlus[i] = Arrays.binarySearch(uniqueC, cValues[i] + k);
        }

        bOccurrences = new Occurrences(bId, uniqueBCount);
        cOccurrences = new Occurrences(cId, uniqueCCount);

        int capacity = 2 * q + 1;
        Node[] nodes = new Node[capacity];
        int nodeCount = 1;
        nodes[0] = new Node(0, n - 1);

        int[] eventNode = new int[q];
        TreeMap<Integer, Integer> segments = new TreeMap<>();
        segments.put(0, 0);

        for (int t = 0; t < q; t++) {
            int d = fs.nextInt() - 1;

            Map.Entry<Integer, Integer> entry = segments.floorEntry(d);
            int parentId = entry.getValue();
            Node parent = nodes[parentId];

            segments.remove(entry.getKey());
            parent.pivot = d;
            eventNode[t] = parentId;

            if (parent.left < d) {
                int childId = nodeCount++;
                nodes[childId] = new Node(parent.left, d - 1);
                parent.leftChild = childId;
                segments.put(parent.left, childId);
            }

            if (d < parent.right) {
                int childId = nodeCount++;
                nodes[childId] = new Node(d + 1, parent.right);
                parent.rightChild = childId;
                segments.put(d + 1, childId);
            }
        }

        long[] freqB = new long[uniqueBCount];
        long[] freqC = new long[uniqueCCount];

        long finalSegmentsCount = 0;
        long removedTotal = 0;
        long[] removedByNode = new long[nodeCount];

        for (int id = 0; id < nodeCount; id++) {
            Node node = nodes[id];
            if (node.pivot == -1) {
                finalSegmentsCount += countLeaf(node.left, node.right, freqB, freqC);
            } else {
                removedByNode[id] = countRemoved(node);
                removedTotal += removedByNode[id];
            }
        }

        long answer = finalSegmentsCount + removedTotal;
        StringBuilder output = new StringBuilder();
        output.append(answer).append('\n');

        for (int t = 0; t < q; t++) {
            answer -= removedByNode[eventNode[t]];
            output.append(answer).append('\n');
        }

        System.out.print(output);
    }

    private static int uniqueCount(long[] sorted) {
        if (sorted.length == 0) return 0;
        int count = 1;
        for (int i = 1; i < sorted.length; i++) {
            if (sorted[i] != sorted[i - 1]) count++;
        }
        return count;
    }
}
